window.EXAM_CHAPTER_DATA["pol_econ"]["04_经济危机与历史趋势"] = {"id":"04_经济危机与历史趋势","name":"经济危机与历史趋势","kps":[{"id":"KP01","name":"资本主义经济危机","file":"","questions":[{"id":"pol_econ_04_经济危机与历史趋势_KP01_1","num":"1","stem":"资本主义经济危机的实质是（　）。","options":{"A":"生产绝对过剩","B":"生产相对过剩","C":"商品供不应求","D":"货币供应不足"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP01_2","num":"2","stem":"资本主义经济危机的根源是（　）。","options":{"A":"生产技术落后","B":"人民消费不足","C":"资本主义基本矛盾","D":"国家政策失误"},"answer":"C"},{"id":"pol_econ_04_经济危机与历史趋势_KP01_3","num":"3","stem":"资本主义基本矛盾是（　）。","options":{"A":"无产阶级与资产阶级的矛盾","B":"生产社会化与生产资料资本主义私人占有之间的矛盾","C":"生产与消费的矛盾","D":"个别企业有组织与社会无政府的矛盾"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP01_4","num":"4","stem":"资本主义再生产周期的顺序是（　）。","options":{"A":"危机—萧条—复苏—高涨","B":"危机—复苏—萧条—高涨","C":"高涨—危机—萧条—复苏","D":"萧条—危机—复苏—高涨"},"answer":"A"},{"id":"pol_econ_04_经济危机与历史趋势_KP01_5","num":"5","stem":"资本主义再生产周期的决定性阶段是（　）。","options":{"A":"危机阶段","B":"萧条阶段","C":"复苏阶段","D":"高涨阶段"},"answer":"A"},{"id":"pol_econ_04_经济危机与历史趋势_KP01_6","num":"6","stem":"资本主义经济危机周期性的物质基础是（　）。","options":{"A":"商品积压","B":"固定资本大规模更新","C":"信用扩张","D":"政府干预"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP01_7","num":"7","stem":"战后资本主义经济危机的新特点不包括（　）。","options":{"A":"危机强度有所减弱","B":"出现\"滞胀\"","C":"经济危机与金融危机交织","D":"经济危机已经消失"},"answer":"D"},{"id":"pol_econ_04_经济危机与历史趋势_KP01_8","num":"8","stem":"1970 年代主要资本主义国家出现的\"滞胀\"是指（　）。","options":{"A":"经济增长与通货膨胀并存","B":"生产停滞与通货膨胀并存","C":"失业下降与物价下降并存","D":"经济高涨与通货紧缩并存"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP01_9","num":"9","stem":"下列说法错误的是（　）。","options":{"A":"经济危机是资本主义基本矛盾尖锐化的强制爆发","B":"危机通过破坏生产力暂时恢复比例","C":"危机可以通过资本主义制度本身根除","D":"危机具有周期性"},"answer":"C"},{"id":"pol_econ_04_经济危机与历史趋势_KP01_10","num":"10","stem":"（逻辑链·分析）资本主义经济危机的根源及其传导链是（　）。","options":{"A":"资本主义基本矛盾（生产社会化与生产资料资本主义私人占有）→ 生产无限扩大趋势 vs 劳动人民购买力相对缩小 → 生产相对过剩 → 危机爆发","B":"人们消费太多","C":"政府干预太多","D":"天灾导致减产"},"answer":"A"},{"id":"pol_econ_04_经济危机与历史趋势_KP01_11","num":"11","stem":"（逻辑链·判断）经济危机周期性爆发的物质基础是（　）。","options":{"A":"固定资本的大规模更新（危机后资本家为降低成本更新设备，带动复苏，又为下一次危机准备条件）","B":"政府换届","C":"太阳黑子","D":"人口周期"},"answer":"A"}]},{"id":"KP02","name":"资本主义的历史地位","file":"","questions":[{"id":"pol_econ_04_经济危机与历史趋势_KP02_1","num":"1","stem":"马克思主义对资本主义历史地位的态度是（　）。","options":{"A":"全盘肯定","B":"全盘否定","C":"历史唯物主义辩证分析","D":"道德义愤地批判"},"answer":"C"},{"id":"pol_econ_04_经济危机与历史趋势_KP02_2","num":"2","stem":"资本主义对生产力发展的作用，马克思、恩格斯认为（　）。","options":{"A":"一直阻碍生产力发展","B":"在不到一百年中创造的生产力比过去一切世代还要多","C":"与封建制相比没有进步","D":"只有破坏没有建设"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP02_3","num":"3","stem":"资本主义的历史局限性不包括（　）。","options":{"A":"以追逐剩余价值为目的","B":"造成阶级对立和两极分化","C":"周期性爆发经济危机","D":"推动了世界市场形成"},"answer":"D"},{"id":"pol_econ_04_经济危机与历史趋势_KP02_4","num":"4","stem":"马克思指出\"两个决不会\"是指（　）。","options":{"A":"资本主义马上灭亡","B":"无论哪一个社会形态，在它所能容纳的全部生产力发挥出来以前，决不会灭亡；新的生产关系在物质条件成熟以前，决不会出现","C":"社会主义永远不会胜利","D":"资本主义不会有任何变化"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP02_5","num":"5","stem":"当代资本主义新变化不包括（　）。","options":{"A":"股份公司普遍化","B":"福利国家制度建立","C":"生产资料公有制占主体","D":"国家干预经济加强"},"answer":"C"},{"id":"pol_econ_04_经济危机与历史趋势_KP02_6","num":"6","stem":"当代资本主义中间阶层扩大，说明（　）。","options":{"A":"无产阶级已经消失","B":"阶级矛盾已经根本解决","C":"阶级结构发生变化，但资产阶级与无产阶级的对立仍然存在","D":"资本主义已经变成社会主义"},"answer":"C"},{"id":"pol_econ_04_经济危机与历史趋势_KP02_7","num":"7","stem":"战后资本主义国家建立福利国家制度，本质上是（　）。","options":{"A":"实行社会主义","B":"为了缓和阶级矛盾、维护资本主义统治","C":"消灭了剥削","D":"实现了共同富裕"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP02_8","num":"8","stem":"资本主义把一切社会关系变成（　）。","options":{"A":"宗法关系","B":"金钱关系（交换价值）","C":"合作关系","D":"等级关系"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP02_9","num":"9","stem":"下列说法错误的是（　）。","options":{"A":"资本主义相对于封建主义是巨大进步","B":"资本主义必然被更高级社会形态代替","C":"当代资本主义新变化改变了资本主义本质","D":"资本主义造成人的异化"},"answer":"C"},{"id":"pol_econ_04_经济危机与历史趋势_KP02_10","num":"10","stem":"（逻辑链·分析）资本主义的历史地位，正确传导是（　）。","options":{"A":"资本主义曾经极大发展生产力（历史进步性）→ 但它建立在剥削基础上，导致两极分化和周期性危机（历史局限性）→ 它是一个过渡的、历史的生产方式","B":"资本主义是永恒的","C":"资本主义只有坏处","D":"资本主义最终完美"},"answer":"A"},{"id":"pol_econ_04_经济危机与历史趋势_KP02_11","num":"11","stem":"（逻辑链·判断）说资本主义是\"历史的、过渡的\"生产方式，意思是（　）。","options":{"A":"它不是从来就有、也不会永远存在，它在历史中产生，也将在历史中被更高级的生产方式取代","B":"它很快就会消失","C":"它是偶然的","D":"它会自动变好"},"answer":"A"}]},{"id":"KP03","name":"资本主义发展的历史趋势","file":"","questions":[{"id":"pol_econ_04_经济危机与历史趋势_KP03_1","num":"1","stem":"资本主义必然被社会主义代替，是由（　）决定的。","options":{"A":"道德愿望","B":"资本主义基本矛盾运动","C":"伟人意志","D":"偶然事件"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP03_2","num":"2","stem":"资本主义为自身灭亡准备的物质条件是（　）。","options":{"A":"农民阶级","B":"高度社会化的大生产","C":"小手工业","D":"封建地主"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP03_3","num":"3","stem":"资本主义的掘墓人是（　）。","options":{"A":"农民阶级","B":"小资产阶级","C":"无产阶级","D":"中产阶级"},"answer":"C"},{"id":"pol_econ_04_经济危机与历史趋势_KP03_4","num":"4","stem":"列宁指出，（　）是社会主义的最充分物质准备，是社会主义的前阶。","options":{"A":"股份公司","B":"垄断资本主义","C":"国家垄断资本主义","D":"跨国公司"},"answer":"C"},{"id":"pol_econ_04_经济危机与历史趋势_KP03_5","num":"5","stem":"股份公司是（　）。","options":{"A":"私有制的彻底消灭","B":"作为私人财产的资本在资本主义生产方式范围内的扬弃","C":"社会主义性质的企业","D":"与资本主义无关的组织形式"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP03_6","num":"6","stem":"资本主义代替封建主义、社会主义代替资本主义，二者共同说明（　）。","options":{"A":"社会发展是杂乱无章的","B":"生产关系一定要适应生产力性质的规律","C":"英雄人物决定历史","D":"社会形态可以随意选择"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP03_7","num":"7","stem":"苏东剧变说明（　）。","options":{"A":"社会主义已经失败","B":"社会主义代替资本主义是短期的","C":"社会主义发展是曲折的，但总趋势不可逆转","D":"资本主义是历史终点"},"answer":"C"},{"id":"pol_econ_04_经济危机与历史趋势_KP03_8","num":"8","stem":"\"两个必然\"是指（　）。","options":{"A":"资本主义必然繁荣、社会主义必然失败","B":"资本主义必然灭亡、社会主义必然胜利","C":"危机必然消失、福利必然扩大","D":"全球化必然倒退、民族国家必然消亡"},"answer":"B"},{"id":"pol_econ_04_经济危机与历史趋势_KP03_9","num":"9","stem":"下列说法错误的是（　）。","options":{"A":"资本主义为新社会准备了物质条件和社会力量","B":"社会主义代替资本主义是长期、曲折的过程","C":"当代资本主义可以通过调整永远存在下去","D":"中国特色社会主义正在实践社会主义的生命力"},"answer":"C"},{"id":"pol_econ_04_经济危机与历史趋势_KP03_10","num":"10","stem":"（逻辑链·分析）资本主义被社会主义取代的历史必然性，正确传导是（　）。","options":{"A":"资本主义基本矛盾随生产社会化发展而尖锐化 → 生产关系成为生产力发展桎梏 → 社会化大生产要求生产资料社会占有 → 资本主义必然被社会主义取代","B":"人们道德提高","C":"工人罢工","D":"资本家良心发现"},"answer":"A"},{"id":"pol_econ_04_经济危机与历史趋势_KP03_11","num":"11","stem":"（逻辑链·判断）资本主义向社会主义过渡是一个长期历史过程，因为（　）。","options":{"A":"生产关系的根本变革需要生产力高度发展、客观条件和主观条件成熟","B":"它明天就发生","C":"它不会发生","D":"它由一场革命自动完成"},"answer":"A"}]}]};
